const c=(s,n={})=>{const{currency:r="",showCurrency:u=!0,decimals:a=1,forceUnit:l=null}=n,t=parseFloat(s)||0;if(t===0)return u?`${r} 0`:"0";const o=Math.abs(t);let e,i="";if(l)switch(l){case"B":e=(t/1e9).toFixed(a),i="B";break;case"M":e=(t/1e6).toFixed(a),i="M";break;case"K":e=(t/1e3).toFixed(a),i="K";break;default:e=t.toFixed(a)}else o>=1e9?(e=(t/1e9).toFixed(a),i="B"):o>=1e6?(e=(t/1e6).toFixed(a),i="M"):o>=1e3?(e=(t/1e3).toFixed(a),i="K"):e=t.toLocaleString("en-US",{minimumFractionDigits:0,maximumFractionDigits:a});return e=parseFloat(e).toString(),u&&r?`${r} ${e}${i}`:`${e}${i}`},m=(s,n="USD")=>c(s,{currency:n,showCurrency:!0,decimals:1}),f=(s,n="compact")=>{const r=parseFloat(s);if(!isFinite(r))return"N/A";switch(n){case"compact":return c(r,{showCurrency:!1});case"full":return r.toLocaleString("en-US",{maximumFractionDigits:2});case"currency":return m(r);default:return c(r,{showCurrency:!1})}};export{f as s};
